package com.honorablemobile

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
class VideoSavedTitleReviewTest {
 private val unsafe=Class.forName("sun.misc.Unsafe").getDeclaredField("theUnsafe").apply{isAccessible=true}.get(null)as sun.misc.Unsafe
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun shelf()=unsafe.allocateInstance(VideoTitleStyleShelf::class.java)as VideoTitleStyleShelf
 private fun owner(a:HonorableVideoEditorActivity)=shelf().also{set(a,"titleStyleShelf",it)}
 private fun style()=NamedVideoTitleStyle("Custom",VideoTitleStyle(0,.067f,false,false))
 private fun commit(a:HonorableVideoEditorActivity,owner:VideoTitleStyleShelf,review:VideoCaptionReviewState,all:Boolean=false,style:NamedVideoTitleStyle=style())=call(a,"commitSavedTitleReview",owner,review,style,all)as Boolean
 @Test fun selectedStylePreservesEverythingElseAndHasOneUndo(){val a=activity();val p=get(a,"project")as VideoEditProject;val before=p.segments;val music=p.soundtrack;val shelf=owner(a);val review=capture(a);assertTrue(commit(a,shelf,review));assertEquals(before[0].copy(titleStyle=style().style),p.segments[0]);assertSame(music,p.soundtrack);assertNull(get(a,"titleStyleShelf"));assertTrue(p.undo());assertEquals(before,p.segments);assertFalse(p.canUndo);assertFalse(commit(a,shelf,review));assertTrue(p.canRedo)}
 @Test fun allClipApplicationKeepsTitlesSourcesTimingCaptionsAndAudio(){val a=activity();val p=get(a,"project")as VideoEditProject;p.restore(listOf(p.segments[0].copy(endMs=2500,title="First"),p.segments[0].copy(startMs=2500,title="Second",speed=2f,volume=.3f)),soundtrack=p.soundtrack);val before=p.segments;val music=p.soundtrack;val shelf=owner(a);assertTrue(commit(a,shelf,capture(a),true));assertEquals(before.map{it.copy(titleStyle=style().style)},p.segments);assertSame(music,p.soundtrack);assertTrue(p.undo());assertEquals(before,p.segments);assertFalse(p.canUndo)}
 @Test fun matchingAppearanceConsumesOwnerWithoutAddingUndo(){val a=activity();val p=get(a,"project")as VideoEditProject;val before=p.segments;val shelf=owner(a);assertFalse(commit(a,shelf,capture(a),style=NamedVideoTitleStyle("Same",before[0].titleStyle)));assertSame(before,p.segments);assertFalse(p.canUndo);assertNull(get(a,"titleStyleShelf"))}
 @Test fun staleForegroundSourceDurationSelectionGenerationSessionRecoveryAndBusyConsumeOnlyOwnShelf(){for(flag in listOf("pause","source","duration","selection","generation","mode","recovery","busy","analysis","draftbusy","music")){val a=activity();val p=get(a,"project")as VideoEditProject;val shelf=owner(a);val review=capture(a);when(flag){"pause"->set(a,"workspaceActive",false);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",5001L);"selection"->set(a,"selectedClip",1);"generation"->set(a,"captionReviewGeneration",review.generation+1);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));"busy"->set(a,"saving",true);"analysis"->set(a,"analyzing",true);"draftbusy"->set(a,"draftBusy",true);else->p.setSoundtrack(p.soundtrack!!.copy(volume=.5f))};val before=p.segments;try{commit(a,shelf,review);fail(flag)}catch(e:java.lang.reflect.InvocationTargetException){assertTrue(flag,e.cause is IllegalStateException)};assertSame(before,p.segments);assertNull(get(a,"titleStyleShelf"))}}
 @Test fun oldShelfCannotConsumeNewOwnerOrApplyAfterUndo(){val a=activity();val old=owner(a);val current=owner(a);val review=capture(a);assertFalse(commit(a,old,review));assertSame(current,get(a,"titleStyleShelf"));assertTrue(commit(a,current,review));val p=get(a,"project")as VideoEditProject;assertTrue(p.undo());assertEquals(true,call(a,"canApplyCaptionReview",review));assertFalse(commit(a,current,review));assertFalse(p.canUndo);assertTrue(p.canRedo)}
 @Test fun shelfAdmissionRequiresExactOwnerAndFullSnapshot(){val a=activity();val shelf=owner(a);val review=capture(a);assertEquals(true,call(a,"canUseSavedTitleReview",shelf,review));assertEquals(false,call(a,"canUseSavedTitleReview",shelf(),review));set(a,"draftBusy",true);assertEquals(false,call(a,"canUseSavedTitleReview",shelf,review));set(a,"draftBusy",false);assertEquals(true,call(a,"canUseSavedTitleReview",shelf,review));set(a,"captionReviewGeneration",review.generation+1);assertEquals(false,call(a,"canUseSavedTitleReview",shelf,review))}
 @Test fun blankWordsStayBlankAndCustomStyleSurvivesExistingCodec(){val a=activity();val p=get(a,"project")as VideoEditProject;assertEquals("",p.segments[0].title);val shelf=owner(a);assertTrue(commit(a,shelf,capture(a)));assertEquals("",p.segments[0].title);val draft=VideoDraft(5000,p.segments,0,0,0,5000,soundtrack=p.soundtrack);assertEquals(draft,VideoDraftCodec.decode(VideoDraftCodec.encode(draft),5000));assertEquals(style().style,p.segments[0].titleStyle)}
 @Test fun pausedBusyAndRecoveryEntryPrecedeShelfWorkersAndWidgets(){for(flag in listOf("pause","busy","recovery")){val a=activity();when(flag){"pause"->set(a,"workspaceActive",false);"busy"->set(a,"saving",true);else->set(a,"recoveryBytes",byteArrayOf(1))};call(a,"savedTitleStyles");assertNull(get(a,"titleStyleShelf"));assertNull(get(a,"captionReviewDialogs"));assertFalse((get(a,"project")as VideoEditProject).canUndo)}}
}
